"""NCERT Class 5 Science Chapter 4: Our School - A Happy Place Data Module"""

CHAPTER_META = {'chapter_num': 4, 'title': 'Our School - A Happy Place', 'subtitle': 'Campus Ecology, Resource Conservation, Safety Drills & Inclusive Empathy', 'class': 'Class 5', 'subject': 'Science'}

SLIDES = [{'id': 1, 'title': 'Happy Campus', 'subtitle': "Aasha & Mohit's Vision of a Safe, Caring & Green School", 'concept_html': '\n            <p>Walking to school on a bright morning, students <strong>Aasha and Mohit</strong> discuss what makes their school truly special. School is more than classrooms and blackboards—it is a <strong>happy place</strong> where every child feels emotionally safe, cared for, respected, and inspired to discover the world.</p>\n            <div class="my-3 p-3 rounded-xl bg-emerald-950/40 border border-emerald-500/30 text-emerald-200 text-xs">\n                🌱 <strong>The Green School Vision:</strong> A forward-thinking campus that manages its own waste, conserves every drop of water, switches off idle electricity, and plants indigenous trees for birds and shade.\n            </div>\n            <p>A sustainable school balances physical infrastructure with environmental stewardship:</p>\n            <div class="mt-3 grid grid-cols-2 gap-2 text-xs">\n                <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-amber-400 block mb-0.5">Emotional Well-being</strong>\n                    Warm welcomes, mutual kindness, inclusive friendships, and freedom from bullying or fear.\n                </div>\n                <div class="p-2.5 rounded-lg bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-emerald-400 block mb-0.5">Eco-Action Campus</strong>\n                    Active composting, rainwater recharge pits, rooftop solar cells, and shaded green verandas.\n                </div>\n            </div>\n        ', 'spoken_text': 'Welcome to our school, a happy place. As students Aasha and Mohit walked through the campus gates, they reflected on why school feels so comforting and joyful. A true school is a haven where every student feels safe, encouraged, and excited to learn. But a great school also cares for our Mother Earth. They imagined transforming their campus into a vibrant green school, where water is cherished, waste is transformed into compost, energy is conserved, and leafy trees shelter singing birds. Every child can be an active leader in creating a happy, healthy school environment.', 'lecture_script': 'Introduction to the concept of a safe, inclusive school, emotional well-being, and the four pillars of a green campus: water, energy, waste, and biodiversity.', 'checkpoints': [{'question': "Which set of characteristics best describes a school that is a genuine 'happy place' for all students?", 'options': ['Strict silence, zero playtime, and locked libraries', 'A safe, welcoming environment where students feel respected, cared for, and inspired to learn', 'A campus with no trees or outdoor playing fields', 'An exam-only building with no social interaction'], 'correct': 1, 'explanation': 'A happy school fosters safety, mutual respect, encouragement, inclusive participation, and joyous experiential learning for every student.', 'study_insight': "Emotional safety and mutual kindness allow children's minds to concentrate better and absorb scientific concepts enthusiastically."}, {'question': "What is the primary objective of creating a 'green school' campus?", 'options': ['Painting all classroom walls and desks dark green', 'Practicing sustainable habits: waste segregation, water conservation, energy saving, and tree planting', 'Replacing all printed books with plastic leaves', 'Forbidding students from drinking water during the day'], 'correct': 1, 'explanation': 'A green school practices ecological responsibility by minimizing waste, conserving water and electricity, and creating biodiverse native plant habitats.', 'study_insight': 'A green school turns the entire campus into a living laboratory where environmental science is practiced daily.'}]}, {'id': 2, 'title': 'School Explorers', 'subtitle': 'Specialized Inquiry Teams Auditing the School Environment', 'concept_html': '\n            <p>To turn green ideas into concrete action, students organize into specialized <strong>School Explorer Teams</strong>. Each team maps, observes, and audits different environmental aspects of the campus:</p>\n            <div class="my-3 grid grid-cols-2 gap-2 text-xs">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-cyan-400 block mb-1">💧 Water Watchers</strong>\n                    Inspect taps, washbasins, drinking coolers, and water tanks to spot dripping leaks and overflowing troughs.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-amber-400 block mb-1">⚡ Electricity Savers</strong>\n                    Check empty classrooms to switch off running fans, tube lights, and monitors during recess and sports periods.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-rose-400 block mb-1">🗑️ Waste Warriors</strong>\n                    Audit campus litter, monitor classroom dustbins, and check if food scraps and papers are separated properly.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-emerald-400 block mb-1">🌳 Green Guardians</strong>\n                    Nurture garden beds, count mature shade trees, water saplings, and record visiting birds and butterflies.\n                </div>\n            </div>\n            <div class="p-2 rounded-lg bg-indigo-950/40 border border-indigo-500/30 text-[11px] text-indigo-300">\n                🚶 <strong>Traffic Trackers:</strong> Observe the main gate during morning drop-off and afternoon dismissal to record vehicle congestion and pedestrian crosswalk safety.\n            </div>\n        ', 'spoken_text': 'To investigate the school environment scientifically, students formed specialized explorer brigades. The Water Watchers walked from tap to tap, listening for leaks and measuring wasted drips. The Electricity Savers patrolled corridors during recess, switching off idle fans and lights left spinning in empty rooms. The Waste Warriors inspected dustbins to make sure fruit peels were separated from paper. Meanwhile, the Green Guardians mapped campus trees and watered young saplings, while the Traffic Trackers observed safety around the school gate.', 'lecture_script': 'The structure and operational roles of student environmental audit brigades: Water Watchers, Electricity Savers, Waste Warriors, Green Guardians, and Traffic Trackers.', 'checkpoints': [{'question': "What is the primary responsibility of the student 'Electricity Savers' team during daily school hours?", 'options': ['Cutting electrical power cables with scissors', 'Patrolling empty rooms to turn off idle fans, lights, and projectors during lunch and recess', 'Removing all electric bulbs permanently from science labs', 'Prohibiting computers from running educational videos'], 'correct': 1, 'explanation': 'Electricity Savers actively audit rooms to ensure lights, fans, and electronics are turned off when not in use, preventing unnecessary energy wastage.', 'study_insight': 'A single ceiling fan left spinning in an empty classroom for an hour wastes over 75 watt-hours of electrical energy.'}, {'question': 'Which student audit team is specifically tasked with monitoring leaking taps and overflowing overhead water tanks?', 'options': ['Traffic Trackers', 'Water Watchers', 'Waste Warriors', 'Green Guardians'], 'correct': 1, 'explanation': 'The Water Watchers team monitors campus plumbing, identifying dripping taps, broken washers, and overflow pipes to conserve drinking water.', 'study_insight': 'Regular student audits allow minor leaks to be reported to school plumbers before thousands of liters are lost.'}]}, {'id': 3, 'title': 'Waste Sorting', 'subtitle': 'The 3Rs Hierarchy & Source Segregation: Wet vs Dry Waste', 'concept_html': '\n            <p>Every school day generates kilograms of discard: pencil shavings, snack wrappers, leftover tiffin peels, and torn paper sheets. Managing this begins with the <strong>3Rs principle: Reduce, Reuse, and Recycle</strong>.</p>\n            <div class="my-3 p-3 rounded-xl bg-cyan-950/40 border border-cyan-500/30 text-cyan-200 text-xs">\n                🔄 <strong>Source Segregation Rule:</strong> Mixing wet organic waste with dry recyclable materials ruins both! Waste must be separated right at the point of disposal into designated bins.\n            </div>\n            <p>The two fundamental waste categories:</p>\n            <div class="mt-3 grid grid-cols-2 gap-2 text-xs">\n                <div class="p-2.5 rounded-xl bg-emerald-950/40 border border-emerald-500/30 text-emerald-200">\n                    <strong class="text-emerald-300 block mb-1">🟢 Wet (Biodegradable) Waste</strong>\n                    Fruit skins, vegetable peels, leftover lunch food, tea leaves, and garden fallen leaves. Decomposes naturally into nutrient-rich compost.\n                </div>\n                <div class="p-2.5 rounded-xl bg-sky-950/40 border border-sky-500/30 text-sky-200">\n                    <strong class="text-sky-300 block mb-1">🔵 Dry (Non-Biodegradable) Waste</strong>\n                    Used paper, cardboard boxes, plastic wrappers, metal foil, glass bottles, and dry pencil shavings. Can be sorted, cleaned, and recycled.\n                </div>\n            </div>\n        ', 'spoken_text': 'Every single day, classrooms produce waste. But trash is only trash when it is mixed up! When wet food scraps are thrown into the same bin as clean paper, the paper gets soiled, soggy, and cannot be recycled. Waste sorting at source is our golden rule. Green bins receive wet, biodegradable organic waste like banana peels and cucumber scraps, which decompose into rich garden compost. Blue bins hold clean, dry items like worksheets and cardboard, ready to be sent to paper recycling mills.', 'lecture_script': 'The 3Rs hierarchy (Reduce, Reuse, Recycle), biodegradable vs non-biodegradable waste classification, and the dual-bin source segregation system.', 'checkpoints': [{'question': 'Why is it critical to separate wet food waste from dry paper waste right at the classroom dustbin?', 'options': ['To make the dustbins look colorful for photography', 'Mixing wet food with paper makes paper soggy, foul-smelling, and impossible to recycle into new books', 'Wet waste cannot touch air under any circumstances', 'Dry paper catches fire whenever it touches banana peels'], 'correct': 1, 'explanation': 'Wet organic food soils dry paper and cardboard, contaminating them with moisture and oils that jam paper-pulping recycling machinery.', 'study_insight': 'Separating waste at source is ten times more efficient than trying to separate mixed garbage at a city landfill.'}, {'question': 'Which of the following discarded school items belongs strictly in the green bin for wet organic waste?', 'options': ['Empty plastic ballpoint pen refills', 'Banana peels, orange skins, and apple cores from lunch boxes', 'Old glossy science magazines', 'Broken steel geometry compasses'], 'correct': 1, 'explanation': 'Fruit skins and food scraps are biodegradable organic matter that microorganisms break down into natural compost for school gardens.', 'study_insight': 'Composting wet waste prevents greenhouse methane gas emissions that form when food rots in deep, airless landfills.'}]}, {'id': 4, 'title': 'Clean Hands', 'subtitle': 'Recycling Chains & The Dignity of Labour of Sanitation Workers', 'concept_html': '\n            <p>What happens after dry waste is deposited in the blue bin? Local <strong>recyclers (kabbadiwalas)</strong> and municipal sanitation teams collect sorted newspapers, cardboard cartons, and plastics to channel them back into production factories.</p>\n            <div class="my-3 p-3 rounded-xl bg-amber-950/40 border border-amber-500/30 text-amber-200 text-xs">\n                🤝 <strong>Dignity of Labour:</strong> Sanitation workers, cleaners, and recyclers perform vital public health work. They keep our classrooms clean, prevent disease epidemics, and protect our natural environment. They deserve our deepest respect, gratitude, and cooperation!\n            </div>\n            <p>How students practice dignity of labour and hygiene:</p>\n            <ul class="mt-2 space-y-1.5 text-xs text-slate-300">\n                <li class="flex items-start space-x-2">\n                    <span class="text-amber-400 font-bold shrink-0">1.</span>\n                    <span><strong>Clean Up After Yourself:</strong> Never leave tiffin crumbs on desks or throw wrappers on the floor expecting staff to pick them up.</span>\n                </li>\n                <li class="flex items-start space-x-2">\n                    <span class="text-amber-400 font-bold shrink-0">2.</span>\n                    <span><strong>Say Thank You:</strong> Greet school housekeeping and sanitation staff with polite smiles and respectful words every day.</span>\n                </li>\n                <li class="flex items-start space-x-2">\n                    <span class="text-amber-400 font-bold shrink-0">3.</span>\n                    <span><strong>Hand Hygiene:</strong> Wash hands thoroughly with soap and water after handling waste or using the restroom.</span>\n                </li>\n            </ul>\n        ', 'spoken_text': 'Who keeps our school corridors sparkling clean every morning? Sanitation workers and paper recyclers carry out essential work that protects community health. Without them, cities would drown in mountains of disease-breeding garbage. The concept of dignity of labour teaches us that all honest work is noble and deserving of deep respect. We can honor sanitation staff by keeping our desks tidy, throwing trash into the proper bin ourselves, greeting them with warmth, and washing our hands thoroughly after waste disposal.', 'lecture_script': 'The informal recycling economy, community hygiene infrastructure, ethical appreciation of the dignity of labour, and personal cleanliness habits.', 'checkpoints': [{'question': 'Why is the work performed by sanitation workers and scrap recyclers considered essential for society?', 'options': ['They hide all garbage underground so it disappears into space', 'They maintain community hygiene, prevent deadly disease outbreaks, and recover recyclable materials to save raw trees and ores', 'They ensure that no new paper mills are ever built', 'They turn old plastic directly into edible sweets'], 'correct': 1, 'explanation': 'Sanitation teams protect public health by preventing pest infestations and water contamination, while recyclers divert valuable materials back into productive manufacturing loops.', 'study_insight': 'Recycling one ton of old newspaper saves approximately 17 mature trees and 26,000 liters of fresh water.'}, {'question': 'Which action by a student best demonstrates respect and dignity of labour toward school housekeeping staff?', 'options': ['Tossing pencil shavings deliberately onto the floor for cleaners to sweep', 'Discarding trash responsibly in dustbins, cleaning personal tiffin crumbs, and greeting staff with polite gratitude', 'Demanding that sanitation workers carry personal school bags', 'Leaving washbasin taps running continuously'], 'correct': 1, 'explanation': 'Dignity of labour is practiced through personal responsibility—cleaning up after oneself and treating sanitation personnel with polite appreciation and respect.', 'study_insight': 'Every honest occupation contributes to the smooth functioning of society and deserves equal respect.'}]}, {'id': 5, 'title': 'Natural Cooling', 'subtitle': 'Passive Architecture: Shade, Cross-Ventilation & Reflective White Roofs', 'concept_html': '\n            <p>Have you ever noticed that some classrooms feel cool and breezy on hot afternoons, while top-floor rooms feel like hot ovens? Buildings can be kept comfortable naturally through <strong>passive thermal cooling</strong>:</p>\n            <div class="my-3 grid grid-cols-3 gap-2 text-center text-xs">\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                    <span class="text-base block mb-1">🌳</span>\n                    <strong class="text-emerald-400 block">Canopy Shade</strong>\n                    Trees block direct solar radiation from heating exterior brick walls.\n                </div>\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                    <span class="text-base block mb-1">🪟</span>\n                    <strong class="text-cyan-400 block">Cross-Ventilation</strong>\n                    Open windows on opposite walls create a cooling breeze, flushing out hot trapped air.\n                </div>\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                    <span class="text-base block mb-1">⚪</span>\n                    <strong class="text-amber-400 block">White Cool Roofs</strong>\n                    White surfaces reflect up to 85% of solar radiation instead of absorbing heat like dark tar roofs.\n                </div>\n            </div>\n            <div class="mt-3 p-2.5 rounded-lg bg-slate-950 border border-slate-800 text-xs text-slate-300">\n                <strong>Color & Solar Absorption:</strong> Dark black surfaces absorb nearly all incoming solar wavelengths, converting radiant light into intense heat. White and light-colored coatings reflect light away, keeping indoor room temperatures 3°C to 5°C cooler!\n            </div>\n        ', 'spoken_text': "Why are some rooms in school naturally cool and breezy while others feel stifling and hot? We do not always need noisy air conditioners to stay cool! Clever architectural science gives us natural cooling. When mature trees shade our classroom walls, brick walls do not heat up. Opening windows on opposite walls allows fresh air to stream through in a continuous draft called cross-ventilation. Furthermore, painting school roofs with reflective white lime or solar-reflective paint bounces the sun's scorching rays right back into the sky, lowering indoor temperatures by up to five degrees.", 'lecture_script': 'Thermal physics of building design: solar albedo and reflective white coatings, convective cross-ventilation, and vegetative shading.', 'checkpoints': [{'question': 'Why does painting school roofs with bright white reflective paint keep top-floor classrooms noticeably cooler in summer?', 'options': ['White paint releases artificial ice into the ceiling tiles', 'White surfaces have high solar reflectance, bouncing away sunlight instead of absorbing it as heat', 'White paint attracts rainy clouds directly above the building', 'White color absorbs all heat and stores it inside the paint layer'], 'correct': 1, 'explanation': 'White surfaces have a high albedo (reflectivity), reflecting up to 80-85% of solar radiation back into the atmosphere, preventing the concrete roof slab from soaking in thermal energy.', 'study_insight': 'In traditional Indian architecture, whitewashing roofs and outer walls with lime (chuna) is an ancient, cost-effective cooling technique.'}, {'question': 'How does cross-ventilation improve classroom comfort on a warm afternoon?', 'options': ['It seals the room completely so air cannot move', 'Opening windows on opposite walls allows cool outside air to enter while expelling stale, warm air', 'It converts nitrogen gas into liquid water', 'It blocks all natural light from entering the room'], 'correct': 1, 'explanation': 'Cross-ventilation harnesses natural pressure differentials. Wind entering through windward windows pushes warm, stagnant indoor air out through leeward windows, refreshing the room.', 'study_insight': 'Warm air is lighter and naturally rises toward the ceiling, so high windows and transoms help hot air escape.'}]}, {'id': 6, 'title': 'Water Leaks', 'subtitle': 'Drop-by-Drop Wastage, Tap Repairs & The Jal Shakti Abhiyan', 'concept_html': '\n            <p>During their morning audit, the Water Watchers found a washroom tap that appeared to be turned off, yet leaked a single drop every few seconds. Is a dripping tap really a big deal?</p>\n            <div class="my-3 p-3 rounded-xl bg-cyan-950/40 border border-cyan-500/30 text-cyan-200 text-xs">\n                💧 <strong>The Shocking Math of Leaks:</strong> A tap dripping just once per second wastes over <strong>30 liters of water every single day</strong>—that is more than <strong>10,000 liters of pure drinking water wasted per year</strong> from a single loose rubber washer!\n            </div>\n            <p>National water conservation initiatives like the <strong>Jal Shakti Abhiyan</strong> promote action across campuses:</p>\n            <div class="mt-3 grid grid-cols-2 gap-2 text-xs text-slate-300">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800">\n                    <strong class="text-cyan-400 block mb-1">🛠️ Rapid Plumbing Repairs</strong>\n                    Replace worn rubber gaskets and washers promptly to stop trickles immediately.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800">\n                    <strong class="text-emerald-400 block mb-1">🌧️ Rooftop Rain Harvesting</strong>\n                    Channel clean monsoon rain from terrace gutters into percolation pits to recharge underground aquifers.\n                </div>\n            </div>\n        ', 'spoken_text': "Drip, drip, drip. Have you ever walked past a tap dripping slowly and thought it was harmless? Let us look at the mathematics. A tap that drips just one drop every second wastes more than thirty liters of precious water in twenty-four hours! That is enough water to supply a family's daily cooking needs. Across a year, a single leaking tap wastes ten thousand liters. Initiatives like the Jal Shakti Abhiyan remind us that every drop matters. When you spot a leak, report it to the plumber immediately and turn taps off firmly after washing your hands.", 'lecture_script': 'Quantitative analysis of dripping tap water wastage, mechanical washer failure, rainwater harvesting recharge pits, and community participation under Jal Shakti Abhiyan.', 'checkpoints': [{'question': 'How much water can a single tap dripping at the rate of one drop per second waste over the course of a full day?', 'options': ['Less than one teaspoon', 'Over 30 liters of clean water', 'Exactly 1,000,000 liters', 'Zero water, because drops evaporate instantly'], 'correct': 1, 'explanation': 'At one drop per second, approximately 86,400 drops fall every day, accumulating into over 30 liters of pure wasted water daily.', 'study_insight': 'Placing a measuring cup beneath a dripping tap for 10 minutes helps students calculate the real rate of campus water loss.'}, {'question': 'What is the primary objective of community initiatives like the Jal Shakti Abhiyan in schools and villages?', 'options': ['Emptying all lakes into underground pipes', 'Promoting water conservation, fixing leaks, planting trees, and building rainwater harvesting systems', 'Replacing fresh tap water with salty ocean water', 'Stopping the monsoon rains from falling'], 'correct': 1, 'explanation': 'Jal Shakti Abhiyan is a national water security campaign focusing on rainwater harvesting, watershed rejuvenation, leak prevention, and groundwater recharge.', 'study_insight': 'Rainwater falling on school rooftops can be filtered through sand and gravel pits to replenish depleted groundwater tables.'}]}, {'id': 7, 'title': 'Tree Canopies', 'subtitle': 'Microclimate Cooling, Air Filtration & Avian Habitats', 'concept_html': '\n            <p>On a hot afternoon, the Green Guardians carried a digital thermometer outdoors. Under direct blistering sunlight on the asphalt basketball court, the ground measured <strong>43°C</strong>. But stepping beneath the dense leafy canopy of a mature neem tree, the temperature plummeted to a gentle <strong>34°C</strong>!</p>\n            <div class="my-3 p-3 rounded-xl bg-emerald-950/40 border border-emerald-500/30 text-emerald-200 text-xs">\n                🌳 <strong>Nature\'s Living Air Conditioners:</strong> Trees cool surroundings not just by physical shade, but through <strong>transpiration</strong>—roots pump groundwater up to leaves, where it evaporates as cool water vapor into the air.\n            </div>\n            <p>Trees provide multifaceted ecosystem services to a school campus:</p>\n            <div class="mt-3 grid grid-cols-3 gap-2 text-center text-xs">\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                    <span class="text-base block mb-1">🐦</span>\n                    <strong class="text-amber-400 block">Wildlife Homes</strong>\n                    Nesting forks for sparrows, barbets, mynas, and honeybees.\n                </div>\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                    <span class="text-base block mb-1">🍃</span>\n                    <strong class="text-emerald-400 block">Air Purifiers</strong>\n                    Leaf surfaces trap airborne dust particles and vehicle exhaust soot.\n                </div>\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                    <span class="text-base block mb-1">💨</span>\n                    <strong class="text-cyan-400 block">Oxygen Factories</strong>\n                    Leaves absorb carbon dioxide during photosynthesis, pumping fresh oxygen.\n                </div>\n            </div>\n        ', 'spoken_text': 'Step out onto the concrete playground on a hot afternoon, and the ground radiates heat like an oven at over forty degrees Celsius. But take five steps beneath the leafy boughs of a big banyan or neem tree, and you instantly feel cool and refreshed. Why? Trees are living air conditioners. Through transpiration, trees draw moisture from deep in the soil and release it as cool invisible water vapor from their leaves. Trees also clean the air, trapping city dust on their bark and providing safe nesting homes for singing sparrows and cheerful squirrels.', 'lecture_script': 'The microclimate buffering of urban tree canopies, evaporative cooling via foliar transpiration, particulate matter trapping, and biodiversity support.', 'checkpoints': [{'question': 'Why is the air beneath a large leafy tree significantly cooler than under a concrete shelter on a sunny afternoon?', 'options': ['Trees release refrigerated coolant gases from their bark', 'Trees combine physical shade with transpiration, releasing cool water vapor that absorbs heat from the surrounding air', 'Trees suck all sunlight inside their trunks permanently', 'The wind only blows where trees are planted'], 'correct': 1, 'explanation': 'Transpiration is the evaporative loss of water from microscopic leaf pores (stomata). Just like sweat cools our skin, evaporating water cools the microclimate beneath the tree canopy.', 'study_insight': 'A single mature tree can transpire hundreds of liters of water daily, providing the cooling equivalent of 10 room-sized air conditioners running continuously.'}, {'question': 'Which of the following represents an ecological benefit provided by native trees on a school campus?', 'options': ['They permanently replace the need for textbooks', 'They trap airborne dust on their leaves, generate oxygen, and provide nesting habitats for local birds and insects', 'They convert soil into pure plastic', 'They stop birds from flying'], 'correct': 1, 'explanation': 'Trees filter particulate matter from the air, release oxygen via photosynthesis, anchor soil with their roots, and shelter diverse birds, bees, and squirrels.', 'study_insight': 'Planting indigenous trees like neem, peepal, and jamun supports local wildlife far better than exotic ornamental trees.'}]}, {'id': 8, 'title': 'Pollinator Gardens', 'subtitle': 'Designing Butterfly Gardens with Nectar & Caterpillar Host Plants', 'concept_html': '\n            <p>The Green Guardians decided to transform an unused sunny patch of campus into a flourishing <strong>Butterfly Garden</strong>. Butterflies do not visit random flowers; they require two specific types of botanical companions:</p>\n            <div class="my-3 grid grid-cols-2 gap-2 text-xs">\n                <div class="p-2.5 rounded-xl bg-rose-950/40 border border-rose-500/30 text-rose-200">\n                    <strong class="text-rose-300 block mb-1">🌺 Nectar Plants (For Adult Butterflies)</strong>\n                    Colorful, nectar-rich flowers like lantana, zinnia, marigold, cosmos, and periwinkle (sadabahar) where winged adult butterflies drink sweet floral nectar.\n                </div>\n                <div class="p-2.5 rounded-xl bg-emerald-950/40 border border-emerald-500/30 text-emerald-200">\n                    <strong class="text-emerald-300 block mb-1">🌿 Host Plants (For Caterpillars)</strong>\n                    Specific leafy plants where female butterflies lay eggs so hatched caterpillars can munch leaves (e.g., curry leaves for Common Mormon, milkweed for Plain Tiger).\n                </div>\n            </div>\n            <p class="text-xs text-slate-300 mt-2">Butterflies are key <strong>pollinators</strong>. As they flit from flower to flower, pollen grains cling to their legs, fertilizing fruits and vegetables across the neighborhood.</p>\n        ', 'spoken_text': 'Did you know that you can invite dazzling winged visitors to your school by planting a butterfly garden? Butterflies need two special kinds of plants to make your garden their home. First, they need nectar plants with bright, flat flowers like marigolds and zinnias, where adult butterflies sip sweet nectar through their straw-like proboscis. Second, they need host plants with tender green leaves, like curry leaf plants or lemon saplings, where mother butterflies lay eggs so hungry baby caterpillars can hatch and feast. By planting both, your campus becomes a sanctuary of biodiversity.', 'lecture_script': 'The biology of butterfly conservation gardens, distinguishing nectar-providing angiosperms from larval host plants, and the ecological role of insect pollination.', 'checkpoints': [{'question': 'What is the difference between a nectar plant and a larval host plant in a school butterfly garden?', 'options': ['Nectar plants are made of plastic while host plants are made of paper', 'Nectar plants provide sweet nectar for adult flying butterflies, while host plants provide specific leaves for caterpillars to feed on', 'Nectar plants grow only in winter while host plants grow only in water', 'There is no difference between them'], 'correct': 1, 'explanation': 'Adult butterflies sip sugary nectar from open flowers for flight energy, but female butterflies strictly deposit eggs on specific host plants that their caterpillars can digest.', 'study_insight': 'For example, the beautiful Lime Butterfly lays its eggs only on citrus and curry leaf foliage.'}, {'question': 'Why are butterflies and bees considered essential insect allies in nature?', 'options': ['They eat all the flowers so plants cannot reproduce', 'They act as pollinators, transferring pollen between flowers so plants can produce fruits, vegetables, and seeds', 'They frighten away birds from school playgrounds', 'They turn garden soil into stone'], 'correct': 1, 'explanation': 'Pollinators transfer pollen from anther to stigma, enabling fertilization and the development of seeds, grains, nuts, and juicy fruits that feed humanity.', 'study_insight': 'Nearly one out of every three bites of food we eat depends directly on insect pollination.'}]}, {'id': 9, 'title': 'Gate Safety', 'subtitle': 'Road Safety, Pedestrian Crossings & Calming School Zone Traffic', 'concept_html': '\n            <p>During morning arrival and afternoon dismissal, the area immediately outside the school gate becomes a bustling storm of auto-rickshaws, school buses, bicycles, parents on scooters, and walking children.</p>\n            <div class="my-3 p-3 rounded-xl bg-amber-950/40 border border-amber-500/30 text-amber-200 text-xs">\n                ⚠️ <strong>The Danger Zone:</strong> Road accidents occur when drivers speed carelessly or pedestrians cross without looking. Establishing strict <strong>School Zone Safety Protocols</strong> protects young lives.\n            </div>\n            <p>Essential safety rules around the school gate:</p>\n            <ul class="mt-2 space-y-1.5 text-xs text-slate-300">\n                <li class="flex items-start space-x-2">\n                    <span class="text-amber-400 font-bold shrink-0">1.</span>\n                    <span><strong>School Speed Limit (20 km/h):</strong> Vehicles must crawl at low speeds near school gates to ensure drivers can brake instantly.</span>\n                </li>\n                <li class="flex items-start space-x-2">\n                    <span class="text-amber-400 font-bold shrink-0">2.</span>\n                    <span><strong>Use the Footpath (Sidewalk):</strong> Walk on elevated pedestrian paths; never run into moving traffic or weave between parked buses.</span>\n                </li>\n                <li class="flex items-start space-x-2">\n                    <span class="text-amber-400 font-bold shrink-0">3.</span>\n                    <span><strong>Stop, Look & Listen:</strong> Before stepping onto the road: Look right, look left, look right again. Cross only when traffic is completely clear.</span>\n                </li>\n            </ul>\n        ', 'spoken_text': 'Every morning, the street outside our school gate fills with speeding cars, buses, and hundreds of walking children. Road accidents happen when people ignore traffic rules or rush carelessly. The Traffic Trackers remind us that school gates must be safe zones. Vehicles must slow down to twenty kilometers per hour. When walking, always stay on the raised footpath. Never sprint into the street or dart between parked vans. When crossing, look right, look left, and look right again, crossing calmly only when vehicles have come to a complete stop.', 'lecture_script': 'Pedestrian safety engineering around school zones, speed calming protocols, vehicle-pedestrian conflict zones, and defensive crossing rules.', 'checkpoints': [{'question': 'What is the recommended maximum driving speed limit for motor vehicles traveling through a designated school zone?', 'options': ['80 km/h for rapid clearance', '20 to 25 km/h to allow drivers to stop instantly if a child steps forward', '120 km/h on express lanes', 'Zero speed, vehicles must be pushed by hand'], 'correct': 1, 'explanation': 'Strict speed limits (20-25 km/h) in school zones drastically reduce vehicle stopping distance and prevent fatal collisions with pedestrians.', 'study_insight': 'A car moving at 20 km/h can stop within 6 meters, whereas a car speeding at 50 km/h takes nearly 25 meters to come to a halt.'}, {'question': 'What is the golden rule every student must practice before crossing any roadway?', 'options': ['Close your eyes and run as fast as possible across the asphalt', 'Look right, look left, look right again, listen for horns, and cross only when traffic is clear', 'Look only at your mobile phone screen while stepping off the curb', 'Wave your arms and expect all moving trucks to vanish'], 'correct': 1, 'explanation': "The defensive crossing sequence (Look Right, Look Left, Look Right Again in India's left-side drive system) ensures full awareness of oncoming traffic.", 'study_insight': 'Always cross at designated zebra crossings where drivers expect pedestrians to cross.'}]}, {'id': 10, 'title': 'Traffic Signs', 'subtitle': 'Deciphering Mandatory, Cautionary & Informatory Road Signboards', 'concept_html': '\n            <p>Road signs are the universal language of transportation. Designed using standardized geometric shapes and colors, they alert, guide, and protect commuters across the country:</p>\n            <div class="my-3 grid grid-cols-3 gap-2 text-center text-xs">\n                <div class="p-2 rounded-xl bg-rose-950/40 border border-rose-500/30 text-rose-200">\n                    <span class="text-base block mb-1">🛑</span>\n                    <strong class="text-rose-300 block">Mandatory (Red Circle)</strong>\n                    Orders what you MUST or MUST NOT do (e.g., Stop, No Entry, Speed Limit 20).\n                </div>\n                <div class="p-2 rounded-xl bg-amber-950/40 border border-amber-500/30 text-amber-200">\n                    <span class="text-base block mb-1">⚠️</span>\n                    <strong class="text-amber-300 block">Cautionary (Triangle)</strong>\n                    Warns of upcoming hazards ahead (e.g., School Ahead, Sharp Curve, Pedestrian Crossing).\n                </div>\n                <div class="p-2 rounded-xl bg-sky-950/40 border border-sky-500/30 text-sky-200">\n                    <span class="text-base block mb-1">ℹ️</span>\n                    <strong class="text-sky-300 block">Informatory (Blue Box)</strong>\n                    Gives helpful directions and facilities (e.g., Hospital, Public Telephone, Bus Stop).\n                </div>\n            </div>\n            <div class="mt-3 p-2.5 rounded-lg bg-slate-900 border border-slate-800 text-xs text-slate-300">\n                🦓 <strong>The Zebra Crossing:</strong> Broad black and white alternating stripes painted across roads. Drivers must stop before the stop line to let pedestrians cross safely.\n            </div>\n        ', 'spoken_text': 'Road signs speak an international language of shapes and colors. Red circular signs are mandatory rules that every driver must obey by law, such as Stop or Speed Limit Twenty. Yellow or white triangular signs with red borders are cautionary warnings, alerting drivers to slow down because a school, speed breaker, or sharp bend lies ahead. Blue rectangular signs are informatory guides showing hospitals, bus stops, and parking. Broad black-and-white zebra stripes give pedestrians a safe corridor where traffic must yield.', 'lecture_script': 'The typology of road traffic signs: circular regulatory signs, triangular warning signs, rectangular informatory signs, and zebra crossing right-of-way regulations.', 'checkpoints': [{'question': "What geometric shape and color are universally used for cautionary (warning) traffic signs like 'School Ahead'?", 'options': ['Green circles with pink borders', 'Equilateral triangles pointing upward with bold red borders and yellow/white background', 'Black stars with neon green dots', 'Blue squares with wavy lines'], 'correct': 1, 'explanation': 'Triangular signs with red borders are universally used as warning signs to prepare drivers for road hazards, pedestrian crossings, and school zones ahead.', 'study_insight': 'The triangular shape catches the peripheral vision of drivers faster than rectangular shapes.'}, {'question': 'What is the legal duty of a motor vehicle driver approaching a painted zebra crossing with pedestrians waiting?', 'options': ['Honk loudly and accelerate through the stripes', 'Slow down and stop completely before the stop line to allow pedestrians to cross safely', 'Switch off headlights and close eyes', 'Park the car directly on top of the zebra stripes'], 'correct': 1, 'explanation': 'Under traffic law, pedestrians have absolute right-of-way on zebra crossings. Drivers must stop before the crossing until pedestrians have crossed safely.', 'study_insight': 'Never overtake another vehicle that has stopped at a zebra crossing, as pedestrians may be crossing in front of it.'}]}, {'id': 11, 'title': 'Fire Drill', 'subtitle': 'Emergency Preparedness: Alarms, Calm Evacuation & Assembly Points', 'concept_html': '\n            <p>Suddenly, a piercing, continuous alarm siren rings throughout the corridors! A smoke alarm has triggered in the science lab. Is it time to scream and run? <strong>NO! Panic is the greatest danger in an emergency.</strong></p>\n            <div class="my-3 p-3 rounded-xl bg-rose-950/40 border border-rose-500/30 text-rose-200 text-xs">\n                🚨 <strong>The Golden Fire Drill Rule:</strong> Move quickly, stay calm, do not run, do not scream, do not collect personal belongings, and follow designated evacuation routes immediately.\n            </div>\n            <p>The 4-Step School Evacuation Routine:</p>\n            <div class="mt-3 grid grid-cols-2 gap-2 text-xs">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-amber-400 block mb-1">1. Stop & Listen</strong>\n                    Cease all classroom activities instantly. Leave school bags, water bottles, and books behind.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-rose-400 block mb-1">2. Single-File Evacuation</strong>\n                    Walk briskly in a single line down staircases; hold handrails and never push or shove.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-cyan-400 block mb-1">3. Assembly Point</strong>\n                    Head directly to the open football ground or central courtyard away from buildings and power lines.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-emerald-400 block mb-1">4. Roll Call & Headcount</strong>\n                    Stand quietly in your class line so teachers can take attendance and ensure every student is safe.\n                </div>\n            </div>\n        ', 'spoken_text': 'When the loud fire alarm shrieks, your heart might race. But panic is your worst enemy! Fire drills teach our bodies how to react calmly and safely. When the alarm sounds, drop your pencil, leave your heavy school bag behind, and stand up quietly. Form a single file line. Walk briskly toward the emergency exit without running, pushing, or screaming. Never take elevators or hide in bathrooms. Head straight to the designated assembly point on the open playground, where class teachers take roll call to ensure every friend is accounted for.', 'lecture_script': 'Emergency response procedures during school fire incidents: alarm recognition, calm single-file evacuation, avoiding stair stampedes, and muster point roll call protocols.', 'checkpoints': [{'question': 'What is the single most important rule of personal conduct when a school fire alarm rings?', 'options': ['Scream at the top of your lungs and sprint blindly down hallways', 'Stay calm, do not panic, leave school bags behind, and walk quickly in a single line toward emergency exits', 'Run back to your desk to find lost pencil sharpeners', 'Lock the classroom door and hide under benches'], 'correct': 1, 'explanation': 'Panic, screaming, and rushing cause dangerous stampedes. Walking briskly and calmly ensures an orderly, fast evacuation without tripping or injuries.', 'study_insight': 'Never stop to gather heavy school bags; human life is infinitely more valuable than books or stationery.'}, {'question': 'Where should students assemble immediately after evacuating a school building during a fire emergency?', 'options': ['In the narrow school basement', 'At the pre-designated open assembly point (like the sports field) well away from buildings and glass windows', 'Inside locked washrooms', 'Under wooden staircases'], 'correct': 1, 'explanation': 'An open assembly ground provides safety from falling debris, shattering window glass, and intense smoke, while allowing teachers to conduct an accurate headcount.', 'study_insight': 'Never leave the assembly area without telling your teacher, or rescue teams might risk their lives searching for you inside a burning building.'}]}, {'id': 12, 'title': 'Smoke Crawl', 'subtitle': 'Toxic Smoke Physics: Why Hot Smoke Rises & How to Crawl Low', 'concept_html': '\n            <p>During a building fire, flames are not the only danger—<strong>smoke and toxic fumes</strong> are often far more dangerous! Fire consumes atmospheric oxygen and generates suffocating carbon monoxide and soot particles.</p>\n            <div class="my-3 p-3 rounded-xl bg-rose-950/40 border border-rose-500/30 text-rose-200 text-xs">\n                🔥 <strong>Thermal Convection Physics:</strong> Hot smoke, burning gases, and poisonous fumes are less dense than room air, so they naturally rise and form a dense, blinding blanket near the ceiling!\n            </div>\n            <p>The Life-Saving "Crawl Low under Smoke" Technique:</p>\n            <div class="mt-3 grid grid-cols-2 gap-2 text-xs">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-amber-400 block mb-1">🧎 Get Down on Hands & Knees</strong>\n                    The cleanest, coolest, breathable air is located in the bottom 30 to 60 cm zone right above the floor.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-cyan-400 block mb-1">🧣 Cover Mouth & Nose</strong>\n                    Use a handkerchief, sleeve, or cloth (dampened with water if possible) to filter out soot particles.\n                </div>\n            </div>\n            <div class="mt-2 p-2 rounded-lg bg-slate-950 border border-slate-800 text-[11px] text-slate-400">\n                🛑 <strong>Never Hide:</strong> Never hide inside cupboards, closets, or under beds. Firefighters in heavy gear need to find you quickly!\n            </div>\n        ', 'spoken_text': 'Did you know that during a fire, smoke is often far more dangerous than the flames themselves? When materials burn, they create thick black smoke and poisonous gases. Because hot air is light, boiling smoke rises rapidly, collecting like a thick blanket against the ceiling. If you walk upright, you will breathe in scorching, toxic fumes. The life-saving secret is to get down on your hands and knees! The coolest, cleanest, breathable air remains down near the floor. Cover your nose and mouth with a cloth, crawl low under the smoke, and make your way to safety.', 'lecture_script': 'Thermal buoyancy of combustion gases, inhalation injury hazards of carbon monoxide and particulates, and the biomechanics of the low-smoke crawl technique.', 'checkpoints': [{'question': 'Why must you drop to your hands and knees and crawl low if a corridor fills with thick fire smoke?', 'options': ['Because crawling is a fun game during drills', 'Hot, poisonous smoke and toxic gases rise toward the ceiling, leaving the cleanest, coolest air in a 30 to 60 cm layer near the floor', 'To hide from the fire alarm sirens', 'Because classroom doors are only 50 cm high'], 'correct': 1, 'explanation': 'Thermal convection causes superheated smoke and lethal gases to rise toward the ceiling. The air closest to the floor is cooler, has more oxygen, and allows clear vision.', 'study_insight': 'Just two or three breaths of dense, hot toxic smoke can cause a person to lose consciousness.'}, {'question': 'Why is it strictly forbidden to hide inside closets, cupboards, or washrooms during a building fire?', 'options': ['Closets are reserved for textbooks only', 'Hiding traps you in confined spaces without escape exits, making it extremely difficult for firefighters to locate and rescue you', 'Washrooms have no electric lights', 'Cupboards make fires spread twice as fast'], 'correct': 1, 'explanation': 'Firefighters wearing heavy masks and air tanks search rooms quickly. Hiding in enclosed closets or under furniture delays rescue while smoke fills the room.', 'study_insight': 'Always move toward an exit. If an exit is blocked, stay near a window and wave a bright cloth to signal firefighters.'}]}, {'id': 13, 'title': 'Kind Actions', 'subtitle': 'Behaviour, Empathy & Civic Stewardship in School Life', 'concept_html': '\n            <p>What transforms a concrete school building into a warm, joyful community? It is the small, everyday choices we make in how we treat our friends, teachers, and shared environment. <strong>What we do matters!</strong></p>\n            <div class="my-3 p-3 rounded-xl bg-indigo-950/40 border border-indigo-500/30 text-indigo-200 text-xs">\n                💖 <strong>The Power of Everyday Empathy:</strong> Empathy means stepping into someone else\'s shoes—feeling what they feel and acting with kindness and fairness.\n            </div>\n            <p>Everyday actions that cultivate collective well-being:</p>\n            <div class="mt-3 grid grid-cols-2 gap-2 text-xs">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-amber-400 block mb-1">Queue Courtesy</strong>\n                    Wait patiently in line at the water cooler, library, and canteen. Take turns without pushing.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-emerald-400 block mb-1">Property Stewardship</strong>\n                    Never scratch or scribble graffiti on wooden desks, walls, or library books. Preserve school heritage.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-cyan-400 block mb-1">Inclusive Games</strong>\n                    Invite classmates standing alone on the playground sidelines to join sports and group activities.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-rose-400 block mb-1">Gentle Words</strong>\n                    Use "Please", "Thank you", and "Sorry" freely. Praise a friend\'s effort and celebrate their success.\n                </div>\n            </div>\n        ', 'spoken_text': 'What makes a school truly feel like a happy second home? It is not the size of the building or the color of the paint. It is how we treat each other every single day. When you wait patiently in line at the drinking water tap instead of pushing, everyone feels respected. When you refuse to scribble on wooden desks, you protect our shared heritage for future younger students. When you invite a shy classmate who is standing alone to join your football game, you build a circle of empathy and friendship. Every kind act creates ripples of happiness across the entire school.', 'lecture_script': 'The social-emotional foundation of positive school climate: pro-social behavior, empathy, public property stewardship, and inclusive peer culture.', 'checkpoints': [{'question': 'Which of the following student behaviors directly contributes to a respectful, peaceful, and happy school environment?', 'options': ['Scribbling graffiti with permanent markers across library books and wooden desks', 'Waiting patiently in queue, sharing playground equipment, and inviting lonely peers to play', 'Pushing younger students in the lunch line', 'Leaving running water taps on in restrooms'], 'correct': 1, 'explanation': 'Queue discipline, sharing, public property respect, and inclusive friendliness foster mutual trust and emotional safety across the campus.', 'study_insight': 'School furniture and library books are shared community treasures; preserving them demonstrates civic maturity.'}, {'question': "What is the meaning of practicing 'empathy' in our daily interactions with classmates?", 'options': ['Making fun of friends who make mistakes in class', 'Understanding and sharing the feelings of another person, and treating them with kindness and fairness', 'Refusing to speak with anyone who does not sit next to you', 'Demanding that everyone agree with your opinion'], 'correct': 1, 'explanation': 'Empathy is the emotional ability to understand what someone else is going through and offering compassionate support.', 'study_insight': 'Practicing empathy prevents teasing and bullying, ensuring that school remains a joyful sanctuary for all.'}]}, {'id': 14, 'title': 'Inclusive Care', 'subtitle': 'Universal Accessibility: Ramps, Tactile Paving & Welcoming Every Friend', 'concept_html': '\n            <p>Imagine arriving at school using a wheelchair, only to find three steep concrete steps at the main entrance with no ramp. How would that feel? A truly happy school is an <strong>inclusive school</strong> where physical barriers are eliminated.</p>\n            <div class="my-3 p-3 rounded-xl bg-emerald-950/40 border border-emerald-500/30 text-emerald-200 text-xs">\n                ♿ <strong>Universal Accessibility (RPwD Act Principles):</strong> Every child, regardless of physical or sensory abilities, has the fundamental right to navigate school buildings independently and with dignity.\n            </div>\n            <p>Essential components of an inclusive campus:</p>\n            <div class="mt-3 grid grid-cols-2 gap-2 text-xs">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-cyan-400 block mb-1">♿ Gentle Ramps & Handrails</strong>\n                    Smooth, non-slip entry ramps beside staircases allowing wheelchair users and injured friends to enter easily.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-amber-400 block mb-1">🟡 Tactile Guiding Tiles</strong>\n                    Textured yellow floor tiles with raised bumps and lines guiding visually challenged students safely through corridors.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-emerald-400 block mb-1">🚻 Accessible Restrooms</strong>\n                    Wide doors, sturdy grab bars, and low washbasins accessible to all physical body types.\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-800 text-slate-300">\n                    <strong class="text-indigo-400 block mb-1">🤝 Peer Buddy Support</strong>\n                    Offering assistance willingly—carrying books or walking alongside friends who need a steady hand.\n                </div>\n            </div>\n        ', 'spoken_text': 'Imagine wanting to join your friends in the science lab, but being blocked by a tall flight of stairs because you use crutches or a wheelchair. A happy school leaves no child behind! Inclusive architecture means designing our school so that everyone can move freely and independently. Gentle concrete ramps with handrails allow wheelchair users to enter every classroom. Textured tactile paths on corridor floors guide friends with visual impairments safely. True inclusion also lives in our hearts, through buddy support and warm encouragement that embraces every single student.', 'lecture_script': 'The principles of universal accessibility, barrier-free built environment (ramps, tactile paving, accessible sanitation), and peer buddy inclusion.', 'checkpoints': [{'question': 'Why should every school building feature gentle ramps with handrails alongside staircases?', 'options': ['To allow bicycle racing inside classroom hallways', 'To ensure students using wheelchairs, crutches, or recovering from injuries can enter buildings independently and safely', 'To make rainwater flow into classrooms faster', 'To prevent teachers from using stairs'], 'correct': 1, 'explanation': 'Ramps provide barrier-free mobility, ensuring children with physical disabilities or temporary injuries can access educational spaces with dignity.', 'study_insight': 'A ramp should have a gentle gradient (slope) of at least 1:12 so a wheelchair user can roll up comfortably without tipping.'}, {'question': 'What is the purpose of the yellow textured tiles with raised lines and bumps installed along school corridors?', 'options': ['They are decorative stickers that glow in the dark', 'They provide tactile pathways that visually impaired students can feel with their shoes or walking canes to navigate safely', 'They warn students that the floor is permanently broken', 'They show where teachers are standing'], 'correct': 1, 'explanation': 'Tactile paving uses raised straight lines to indicate safe walking paths and raised blister dots to warn of upcoming stairs, doors, or turns for visually impaired pedestrians.', 'study_insight': 'Tactile pathways allow students with blindness to navigate entire school campuses with full independence.'}]}, {'id': 15, 'title': 'Energy Savers', 'subtitle': 'Conservation Habits: Natural Daylighting, Idle Loads & Solar Energy', 'concept_html': '\n            <p>Thermal power plants burn hundreds of tons of fossil fuel coal to generate electricity, releasing greenhouse gases that warm our planet. Conserving electricity on our school campus directly protects the Earth\'s climate!</p>\n            <div class="my-3 p-3 rounded-xl bg-amber-950/40 border border-amber-500/30 text-amber-200 text-xs">\n                💡 <strong>The Energy Savers\' Motto:</strong> "A unit of electricity saved at the switch is more valuable than a unit generated at a polluting power station!"\n            </div>\n            <p>Smart energy conservation habits for every student:</p>\n            <ul class="mt-2 space-y-1.5 text-xs text-slate-300">\n                <li class="flex items-start space-x-2">\n                    <span class="text-amber-400 font-bold shrink-0">1.</span>\n                    <span><strong>Harness Natural Daylighting:</strong> Open curtains and windows on bright sunny mornings; use sunshine instead of burning artificial tube lights.</span>\n                </li>\n                <li class="flex items-start space-x-2">\n                    <span class="text-amber-400 font-bold shrink-0">2.</span>\n                    <span><strong>Switch Off During Breaks:</strong> Assign a classroom energy monitor to turn off all ceiling fans and lights before leaving for assembly, sports, or lunch.</span>\n                </li>\n                <li class="flex items-start space-x-2">\n                    <span class="text-amber-400 font-bold shrink-0">3.</span>\n                    <span><strong>Eliminate Standby Loads:</strong> Turn off computer lab monitors, smartboards, and audio speakers at the wall plug; avoid vampire power drain.</span>\n                </li>\n            </ul>\n        ', 'spoken_text': 'Did you know that most of the electricity powering our fans and lights comes from burning coal in distant power plants? Every time a fan spins in an empty room, fossil fuels are burned and smoke enters our atmosphere. The Electricity Savers remind us of our power to make a difference. On bright sunny mornings, slide open the curtains and let golden sunlight illuminate your notebooks. Whenever your class leaves for recess or sports, flip the switches off. Turning off idle appliances at the plug stops silent energy drain, keeping our air clean and our campus green.', 'lecture_script': 'Electrical energy conservation, fossil fuel thermal generation impacts, natural daylight harvesting, phantom standby load elimination, and student energy audits.', 'checkpoints': [{'question': 'What is an immediate environmental benefit of switching off lights and fans in empty school classrooms?', 'options': ['It makes the classroom colder than the North Pole', 'It reduces electricity consumption, decreasing coal burning at power plants and cutting harmful air pollution', 'It turns electrical cables into copper water pipes', 'It stops the sun from shining outside'], 'correct': 1, 'explanation': 'Saving electricity directly reduces the demand on thermal power grids, cutting coal combustion and greenhouse gas emissions.', 'study_insight': 'If every school in a city turned off lights during recess, megawatts of clean energy would be saved every single hour.'}, {'question': "What is 'daylight harvesting' in classroom design?", 'options': ['Catching sunlight in glass jars to sell at markets', 'Opening curtains and large windows to utilize free, natural solar light instead of turning on electric tube lights', 'Planting wheat inside school desks', 'Covering windows with dark cardboard during sunny mornings'], 'correct': 1, 'explanation': "Daylight harvesting relies on architectural natural lighting. Utilizing daylight saves electricity, reduces eye strain, and improves students' focus and mood.", 'study_insight': 'Natural daylight provides full-spectrum light that stimulates healthy circadian alertness in growing children.'}]}, {'id': 16, 'title': 'Happiness Tree', 'subtitle': 'Reflective Action: Cultivating Gratitude, Kindness & Eco-Pledges', 'concept_html': '\n            <p>To conclude their environmental and social investigation, Aasha, Mohit, and their classmates constructed a magnificent <strong>Happiness Tree</strong> on a large recycled bulletin board in the central hallway.</p>\n            <div class="my-3 p-3 rounded-xl bg-emerald-950/40 border border-emerald-500/30 text-emerald-200 text-xs">\n                🌳 <strong>The Happiness Tree Tradition:</strong> A bare painted tree trunk that grows hundreds of colorful paper leaves, each inscribed with a real act of kindness, an eco-action, or a note of heartfelt gratitude.\n            </div>\n            <p>Categories of leaves that bring the tree to life:</p>\n            <div class="mt-3 grid grid-cols-3 gap-2 text-center text-xs">\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                    <span class="text-base block mb-1">🍃</span>\n                    <strong class="text-emerald-400 block">Eco Pledges</strong>\n                    "I fixed a dripping tap", "I brought a reusable cloth napkin", "I watered the neem sapling".\n                </div>\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                    <span class="text-base block mb-1">💖</span>\n                    <strong class="text-rose-400 block">Kindness Acts</strong>\n                    "I helped a classmate pick up dropped pencils", "I shared my crayons with a friend".\n                </div>\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-800">\n                    <span class="text-base block mb-1">🙏</span>\n                    <strong class="text-amber-400 block">Gratitude Notes</strong>\n                    "Thank you to our school bus driver", "Thank you to the bhaiya who cleans our hallway".\n                </div>\n            </div>\n        ', 'spoken_text': 'To celebrate their journey, the students created a magnificent Happiness Tree in the school corridor. They started with a painted brown trunk on recycled paper. Every time a student performed a kind action, planted a sapling, or thanked a sanitation worker, they wrote it on a green paper leaf and pinned it to the branches. Within weeks, the bare tree bloomed into a dense canopy of kindness, gratitude, and sustainability. Our school becomes a happy place through the choices we make every day. Together, we can make every corner of our campus safe, green, and joyful.', 'lecture_script': 'Social-emotional synthesis through the Happiness Tree project: gratitude expression, collective eco-commitments, positive school culture, and student agency.', 'checkpoints': [{'question': "What does each paper leaf on the school's 'Happiness Tree' represent?", 'options': ['A list of test marks and exam ranks', 'A real student act of kindness, an environmental conservation pledge, or a note of gratitude to campus workers', 'A price tag for purchasing school uniforms', 'A complaint about rainy weather'], 'correct': 1, 'explanation': 'The Happiness Tree serves as a visual celebration of positive contributions—recognizing kindness, environmental action, and gratitude across the school community.', 'study_insight': 'Displaying collective positive actions encourages peer emulation, inspiring other students to practice kindness daily.'}, {'question': 'What is the overarching lesson learned by Aasha and Mohit during their school environment exploration?', 'options': ['Students should never care about what happens outside their classrooms', 'A happy and sustainable school is created through collective responsibility, empathy, conservation, and daily kind actions', 'Only adult engineers can keep a school clean and safe', 'School happiness depends entirely on the size of the computer screens'], 'correct': 1, 'explanation': 'Every student holds the power to shape school culture through daily mindful habits—saving resources, practicing safety, welcoming friends, and caring for nature.', 'study_insight': 'True environmental education is not just memorizing facts, but taking active responsibility for the world around us.'}]}]

QUIZ_QUESTIONS = [{'id': 1, 'question': "What is the primary defining characteristic of an eco-friendly 'green school'?", 'options': ['Painting every classroom wall and bench dark green', 'A campus that actively manages waste, conserves water, uses electricity responsibly, and nurtures trees', 'Replacing all printed textbooks with artificial plastic models', 'Locking all gates so students cannot enter the playground'], 'answer': 1, 'explanation': 'A green school practices holistic environmental stewardship by minimizing waste, conserving water and energy, and cultivating native biodiversity.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Core Concept of a Green School:</strong></p>\n                <p>A green school transforms the campus into a living environmental laboratory. It engages students and staff in sustainable daily habits: segregating waste, composting wet scraps, harvesting rainwater, harvesting natural daylight, and planting shade trees.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the correct definition.</p>\n            </div>\n        '}, {'id': 2, 'question': 'Which student explorer team is responsible for inspecting classroom dustbins and ensuring proper waste segregation?', 'options': ['Traffic Trackers', 'Waste Warriors', 'Electricity Savers', 'Water Watchers'], 'answer': 1, 'explanation': 'The Waste Warriors team audits waste generation, checks that dry and wet waste are separated into proper bins, and monitors composting pits.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Team Functional Specialization:</strong></p>\n                <ul class="list-disc pl-4 space-y-1">\n                    <li><strong>Waste Warriors:</strong> Litter auditing, bin checks, and compost monitoring.</li>\n                    <li><strong>Water Watchers:</strong> Detecting leaks and monitoring water tanks.</li>\n                    <li><strong>Electricity Savers:</strong> Turning off idle fans and lights.</li>\n                    <li><strong>Green Guardians:</strong> Caring for trees, gardens, and visiting pollinators.</li>\n                </ul>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the Waste Warriors.</p>\n            </div>\n        '}, {'id': 3, 'question': "In the waste hierarchy known as the '3Rs', which action is considered the most effective first step for environmental protection?", 'options': ['Recycling all materials repeatedly forever', 'Reducing waste generation at the source by avoiding unnecessary consumption', 'Burying mixed waste in deep city landfills', 'Burning waste piles in open playgrounds'], 'answer': 1, 'explanation': 'Reducing waste at the source prevents waste from being created in the first place, saving raw materials, water, and industrial processing energy.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>The 3Rs Hierarchy:</strong></p>\n                <p>The 3Rs are prioritized in order of ecological efficiency: <strong>Reduce > Reuse > Recycle</strong>. Reducing is paramount because preventing waste generation avoids extraction of raw resources, manufacturing pollution, and transport emissions altogether.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the top priority.</p>\n            </div>\n        '}, {'id': 4, 'question': "Why is 'source segregation' (separating wet and dry waste at the classroom bin) essential for successful waste management?", 'options': ['To make the classroom look like a colorful art exhibition', 'Wet organic scraps soil dry paper and plastic, rendering recyclable materials contaminated and unrecyclable', 'Wet waste turns all metal cans into combustible gas', 'Dry waste cannot be touched by air currents'], 'answer': 1, 'explanation': 'Mixing wet food with dry recyclables contaminates paper and cardboard with moisture and oils, causing foul odors and making mechanical recycling impossible.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Principles of Source Segregation:</strong></p>\n                <p>When waste is mixed, clean dry paper absorbs moisture and grease from food scraps, jamming paper recycling pulpers. Separating waste at source allows wet waste to become rich compost and dry materials to enter recycling factories cleanly.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B explains the necessity of source separation.</p>\n            </div>\n        '}, {'id': 5, 'question': 'Which of the following discarded lunch items belongs strictly in the green bin for wet organic waste?', 'options': ['Plastic juice pouch straws', 'Banana peels, orange skins, and apple cores', 'Torn aluminum tiffin wrapping foil', 'Used dry ballpoint pen plastic bodies'], 'answer': 1, 'explanation': 'Fruit peels and vegetable scraps are biodegradable organic waste that naturally decompose into rich compost when placed in the green bin.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Green Bin Classification:</strong></p>\n                <p>The green bin is universally reserved for biodegradable organic matter: food leftovers, fruit skins, vegetable peels, tea leaves, and garden leaves. Microorganisms break these down aerobically into nutrient-rich humus (compost).</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B belongs in the green bin.</p>\n            </div>\n        '}, {'id': 6, 'question': 'Which items belong in the blue bin designated for dry, recyclable non-biodegradable waste?', 'options': ['Leftover sambar and boiled rice', 'Used exam question papers, cardboard cartons, clean plastic wrappers, and metal tins', 'Wet tea leaves and banana skins', 'Rotten tomatoes and watermelon rinds'], 'answer': 1, 'explanation': 'The blue bin collects clean, dry non-biodegradable items: scrap paper, cardboard, plastics, glass, and metal, which are sorted and recycled.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Blue Bin Classification:</strong></p>\n                <p>Blue bins collect clean recyclable dry discards: stationery papers, worksheets, cardboard packaging, clean plastic wrappers, and tins. These materials are forwarded to scrap recyclers for industrial reprocessing.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B belongs in the blue bin.</p>\n            </div>\n        '}, {'id': 7, 'question': "What is meant by the ethical principle of the 'Dignity of Labour' in school life?", 'options': ['Believing that only office workers do valuable work', 'Respecting, appreciating, and valuing all forms of honest work equally, including sanitation workers and scrap recyclers', 'Forbidding students from ever cleaning their own desks', 'Assigning cleaning duties only as a punishment'], 'answer': 1, 'explanation': 'Dignity of labour recognizes that all honest work contributes to society. Sanitation staff and recyclers protect public health and deserve our deepest respect and gratitude.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Dignity of Labour:</strong></p>\n                <p>This core ethical value teaches that no honest occupation is inferior. Sanitation workers and recyclers perform vital community health duties by preventing disease outbreaks and conserving natural resources. We honor them through polite respect and cleaning up after ourselves.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B defines dignity of labour.</p>\n            </div>\n        '}, {'id': 8, 'question': 'How many mature trees are conserved on average by recycling one single metric ton of discarded school paper?', 'options': ['Zero trees', 'Approximately 17 mature trees and thousands of liters of water', 'Exactly 1,000,000 trees', 'Half a small blade of grass'], 'answer': 1, 'explanation': 'Recycling one ton of scrap paper saves roughly 17 mature forest trees, 26,000 liters of water, and significant industrial electricity.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Ecological Math of Paper Recycling:</strong></p>\n                <p>Virgin paper manufacturing requires felling trees and boiling wood pulp with heavy water and chemicals. Recycling one ton of collected classroom paper spares 17 mature trees from deforestation and prevents water pollution.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the proven environmental saving.</p>\n            </div>\n        '}, {'id': 9, 'question': 'What harmful environmental consequence occurs when mixed wet food waste is dumped into municipal landfills instead of being composted?', 'options': ['It turns into pure solid gold underground', 'It rots in airless conditions, producing methane—a potent greenhouse gas that drives global climate change', 'It converts all landfill soil into drinking water', "It cools down the entire Earth's atmosphere permanently"], 'answer': 1, 'explanation': 'Deep in landfills, anaerobic bacteria decompose buried food without oxygen, generating methane gas, which traps 28 times more atmospheric heat than carbon dioxide.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Anaerobic Landfill Emissions:</strong></p>\n                <p>When food scraps are buried under mixed trash, oxygen is absent. Anaerobic methanogenic bacteria break down the food, releasing methane ($CH_4$). Aerobic composting in schools allows oxygen flow, turning waste into harmless organic fertilizer instead.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B explains the danger of landfilling food scraps.</p>\n            </div>\n        '}, {'id': 10, 'question': 'Which classroom habit best demonstrates personal responsibility and civility regarding waste?', 'options': ["Throwing pencil shavings under your friend's desk when the teacher is looking away", 'Collecting your own pencil shavings and snack wrappers, and placing them neatly in designated bins', 'Leaving crushed tiffin foil on the floor for cleaning staff to pick up', 'Shoving plastic wrappers into the gaps between desk planks'], 'answer': 1, 'explanation': 'Personal responsibility means cleaning up after yourself, depositing trash in the correct bin, and maintaining shared classroom spaces cleanly.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Personal Stewardship:</strong></p>\n                <p>A green campus begins with personal discipline. Discarding personal pencil shavings and snack wrappers into the correct dustbin shows respect for classmates and campus housekeeping workers.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the responsible habit.</p>\n            </div>\n        '}, {'id': 11, 'question': 'What are the three fundamental principles of passive natural cooling used in eco-friendly school building architecture?', 'options': ['Electric air conditioners, closed glass windows, and black tar roofs', 'Tree canopy shade, cross-ventilation through opposing windows, and reflective white cool roofs', 'Underground heaters, plastic curtains, and neon lights', 'Sealed doors, diesel fans, and asphalt courtyards'], 'answer': 1, 'explanation': 'Passive architecture relies on natural physics: tree shade blocks solar heat, cross-ventilation creates convective air currents, and white roofs reflect radiant light.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Passive Thermal Architecture:</strong></p>\n                <p>Passive cooling maintains comfortable indoor temperatures without high electricity consumption by combining three scientific methods: vegetative shading, cross-ventilation breezes, and high-albedo reflective roof coatings.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B correctly lists the three principles.</p>\n            </div>\n        '}, {'id': 12, 'question': 'Why does a rooftop coated with reflective white lime or solar paint keep classrooms 3°C to 5°C cooler than a dark black tar roof?', 'options': ['White surfaces attract cold polar winds from the sky', 'White surfaces possess high solar reflectance (albedo), reflecting incoming sunlight instead of absorbing thermal radiation', 'White paint turns concrete into solid ice', 'Black surfaces repel all forms of light'], 'answer': 1, 'explanation': 'White surfaces have high albedo, bouncing back up to 80-85% of solar energy. Dark surfaces absorb solar wavelengths, conducting heat into ceilings.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Solar Albedo & Heat Absorption:</strong></p>\n                <p>Albedo is the fraction of solar radiation reflected by a surface. Dark roofs have low albedo, absorbing solar photons and heating up to 65°C. White roofs have high albedo, reflecting sunlight away and keeping roof slabs close to ambient air temperature.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the physical explanation.</p>\n            </div>\n        '}, {'id': 13, 'question': 'How does cross-ventilation create a refreshing breeze inside a classroom on a warm afternoon?', 'options': ['It freezes the air molecules into solid blocks', 'Opening windows on opposite walls allows outdoor wind pressure to push out hot, stagnant air and replace it with cooler moving air', 'It turns classroom oxygen into liquid nitrogen', 'It permanently seals all doors so air cannot escape'], 'answer': 1, 'explanation': 'Cross-ventilation uses wind pressure differentials across opposite exterior walls to draw in fresh outdoor air while venting warm indoor air.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Fluid Dynamics of Cross-Ventilation:</strong></p>\n                <p>Wind striking one side of a building creates positive pressure, while the opposite sheltered side experiences negative suction. Opening windows on both sides creates a continuous draft that flushes out heat and carbon dioxide.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B describes cross-ventilation dynamics.</p>\n            </div>\n        '}, {'id': 14, 'question': 'How much clean drinking water is lost each day from a single school washroom tap that drips at the rate of one drop per second?', 'options': ['Less than 50 milliliters', 'Over 30 liters per day (more than 10,000 liters per year)', 'Exactly 500,000 liters', 'Zero, because dripping water is destroyed by air'], 'answer': 1, 'explanation': 'At 1 drop per second, 86,400 drops fall every 24 hours, adding up to over 30 liters daily and exceeding 10,000 liters annually from a single tap.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>The Quantitative Math of Water Loss:</strong></p>\n                <p>A single water drop measures approximately 0.05 mL. At 1 drop per second: 60 drops/min × 60 min × 24 hr = 86,400 drops/day = 4.3 liters every 4 hours, totaling over 30 liters daily. Over 365 days, this exceeds 10,000 liters!</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the correct calculation.</p>\n            </div>\n        '}, {'id': 15, 'question': 'What is the most frequent mechanical cause of a dripping tap that will not shut off tightly?', 'options': ['The tap pipe is made of solid copper', 'A worn, cracked, or hardened internal rubber washer (gasket) that fails to seal the valve seat', 'The water inside the pipe is too cold to flow', 'The metal handle is painted blue'], 'answer': 1, 'explanation': 'Water taps rely on a flexible rubber washer to press against a metal seat. Over time, friction and mineral deposits degrade the washer, allowing water to seep past.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Plumbing Mechanics:</strong></p>\n                <p>Inside a compression tap, turning the spindle presses a rubber washer against the valve seat. When this washer wears out, cracks, or hardens, it leaves microscopic gaps through which pressurized water continuously drips.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the mechanical cause.</p>\n            </div>\n        '}, {'id': 16, 'question': 'What key national water conservation objective is promoted under community programs like the Jal Shakti Abhiyan?', 'options': ['Paving entire school playgrounds with impervious concrete slabs', 'Rooftop rainwater harvesting, recharging groundwater aquifers, repairing leaks, and planting trees', 'Emptying clean lake water into city gutters', 'Stopping all drinking water supplies to schools'], 'answer': 1, 'explanation': 'Jal Shakti Abhiyan is a nationwide water conservation campaign focused on rainwater harvesting, watershed management, groundwater recharge, and intensive afforestation.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Jal Shakti Abhiyan Mandate:</strong></p>\n                <p>Launched by the Government of India, this mission rallies schools, panchayats, and citizens to capture monsoon rainwater, fix leaky infrastructure, restore traditional water bodies, and plant trees to secure water for future generations.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B states the mission goals.</p>\n            </div>\n        '}, {'id': 17, 'question': 'Through which biological process do mature leafy trees actively lower the surrounding air temperature on a hot afternoon?', 'options': ['Photosynthetic combustion', 'Transpiration—evaporating water from leaf pores (stomata) which absorbs heat from the air', 'Releasing liquid ice through trunk roots', 'Absorbing all atmospheric nitrogen'], 'answer': 1, 'explanation': 'Transpiration is the evaporative cooling engine of trees. Water evaporating through leaf stomata absorbs ambient heat, acting like a natural air conditioner.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Foliar Transpiration Cooling:</strong></p>\n                <p>Tree roots pump water from soil up to the leaves. Solar warmth evaporates this water through microscopic leaf stomata. The latent heat of vaporization absorbs thermal energy from surrounding air, lowering the microclimate temperature by 3°C to 8°C.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the biological mechanism.</p>\n            </div>\n        '}, {'id': 18, 'question': 'Why did the Green Guardians measure a 9°C temperature difference between the open basketball court and beneath a neem tree?', 'options': ['The basketball court was on fire', 'Asphalt absorbs and re-radiates intense solar heat, while the tree canopy blocks sunlight and cools the air through transpiration', 'The neem tree releases artificial liquid nitrogen', 'The thermometer was broken on the court'], 'answer': 1, 'explanation': 'Dark pavement absorbs solar energy and radiates it as heat (urban heat island effect), whereas tree leaves block direct rays and transpire cool water vapor.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Microclimate Comparison:</strong></p>\n                <p>Asphalt and concrete surfaces have high thermal mass, soaking in solar radiation and reaching temperatures over 45°C. Tree canopies intercept sunlight before it hits the ground, and leaf transpiration actively removes heat.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B accurately explains the difference.</p>\n            </div>\n        '}, {'id': 19, 'question': 'Which of the following indigenous Indian trees is celebrated for purifying air, providing dense shade, and supporting diverse native wildlife?', 'options': ['Artificial plastic palm trees', 'Neem, Peepal, Banyan, and Jamun trees', 'Thorny desert cactus in closed pots', 'Ornamental plastic ivy vines'], 'answer': 1, 'explanation': 'Native keystone species like neem, peepal, and banyan thrive in Indian climates, providing large shade canopies, filtering air, and feeding indigenous birds and insects.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Ecological Value of Native Trees:</strong></p>\n                <p>Indigenous Indian trees co-evolved with local fauna. Neem has antimicrobial properties and dense leaves; banyan and peepal produce figs that sustain barbets, parakeets, and fruit bats; jamun provides sweet summer berries and butterfly host foliage.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the correct group of native trees.</p>\n            </div>\n        '}, {'id': 20, 'question': 'How do leafy tree canopies on school perimeters help clean the air that students breathe?', 'options': ['By vaporizing air molecules into thin dust', 'Rough, hairy leaf surfaces trap airborne dust, soot, and fine particulate matter, washing it harmlessly into the soil during rain', 'By producing carbon monoxide gas', 'By blocking all oxygen from entering the campus'], 'answer': 1, 'explanation': 'Leaves and bark act as physical air filters, trapping particulate matter (PM2.5 and PM10) from vehicle exhausts, which is later washed into soil by rain.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Particulate Matter Filtration:</strong></p>\n                <p>Tree leaves have microscopic ridges, hairs, and waxy coatings that physically intercept airborne dust and soot particles from surrounding traffic. This green barrier drastically reduces air pollution in classrooms.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B describes tree particulate filtration.</p>\n            </div>\n        '}, {'id': 21, 'question': "What is the biological difference between 'nectar plants' and 'larval host plants' in a butterfly conservation garden?", 'options': ['Nectar plants are painted blue while host plants are painted red', 'Nectar plants provide sugary nectar for flying adult butterflies, while host plants provide specific foliage where mother butterflies lay eggs and caterpillars feed', 'Nectar plants only grow in winter while host plants grow only in desert sand', 'There is no difference between them'], 'answer': 1, 'explanation': 'Adult butterflies sip nectar from open flowers for flight energy, but female butterflies strictly deposit eggs on specific host plants whose leaves nourish caterpillars.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Butterfly Garden Botany:</strong></p>\n                <p>Butterflies undergo complete metamorphosis: egg, larva (caterpillar), pupa, and adult. Adult butterflies drink nectar from many bright flowers. However, caterpillars are specialized herbivores that can only feed on specific host plants (like curry leaves or milkweed).</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the scientific distinction.</p>\n            </div>\n        '}, {'id': 22, 'question': 'Which of the following common garden plants provides rich nectar sources for adult butterflies on a school campus?', 'options': ['Plastic ferns', 'Marigold, Zinnia, Cosmos, and Periwinkle (Sadabahar)', 'Thorny iron fencing poles', 'Dry gravel stones'], 'answer': 1, 'explanation': "Marigold, zinnia, cosmos, and sadabahar have open, nectar-rich blossoms with landing platforms ideal for butterflies' delicate legs and long proboscis.", 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Nectar Floral Structure:</strong></p>\n                <p>Butterflies prefer composite flowers with accessible nectar wells and broad petals where they can perch comfortably. Zinnias, marigolds, and cosmos flower profusely in sunny school plots, providing continuous nectar.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B correctly lists nectar plants.</p>\n            </div>\n        '}, {'id': 23, 'question': 'Which plant serves as the specific larval host plant for the Common Mormon butterfly to lay its eggs and feed its caterpillars?', 'options': ['Hardwood teak logs', 'Curry leaf plant (Kadi Patta) and citrus saplings', 'Dry wheat straw', 'Cement concrete paving blocks'], 'answer': 1, 'explanation': 'The Common Mormon butterfly lays its round eggs on the tender leaves of curry leaf (Murraya koenigii) and citrus plants, which the hatched caterpillars eat.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Host Plant Specificity:</strong></p>\n                <p>Female butterflies use chemical sensors on their feet to identify the precise botanical species. The Common Mormon and Lime Butterfly require citrus family plants (Rutaceae), including the common kitchen curry leaf plant.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the specific host plant.</p>\n            </div>\n        '}, {'id': 24, 'question': 'Why are insect pollinators like butterflies and honeybees essential for the human food supply?', 'options': ["They consume agricultural crops so people don't have to harvest them", 'They transfer pollen between flower blossoms, enabling plants to produce fruits, vegetables, nuts, and viable seeds', 'They frighten away birds from school playgrounds', 'They turn garden soil into pure sand'], 'answer': 1, 'explanation': 'Pollinators transfer pollen grains from male anthers to female stigmas. Without pollination, flowering plants cannot develop fruits, vegetables, or seeds.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>The Crucial Role of Pollinators:</strong></p>\n                <p>Over 75% of the world\'s leading food crops depend directly on insect pollination. When butterflies and bees drink nectar, pollen sticks to their bodies and is carried to other flowers, enabling plant fertilization and fruit production.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B explains the role of pollinators.</p>\n            </div>\n        '}, {'id': 25, 'question': 'Why is a strict motor vehicle speed limit of 20 to 25 km/h enforced in designated school zones?', 'options': ['To make school buses arrive late for classes', 'To shorten stopping distances so drivers can brake instantly if an excited student steps onto the roadway', 'Because vehicles cannot travel faster than 25 km/h in reverse', 'To make car engines produce louder exhaust sounds'], 'answer': 1, 'explanation': 'Lowering vehicle speed to 20-25 km/h drastically cuts braking distance and reduces pedestrian collision impact forces, preventing severe injuries.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Physics of Vehicle Stopping Distance:</strong></p>\n                <p>Stopping distance equals reaction distance plus braking distance. At 20 km/h, a car stops within 6 meters. At 50 km/h, it takes 25 meters. In school zones with unpredictable child movement, slow speeds prevent accidents.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the safety rationale.</p>\n            </div>\n        '}, {'id': 26, 'question': 'What is the correct, safe pedestrian sequence taught to students before stepping across any road in India?', 'options': ['Look straight down at your shoes and run fast', 'Look Right, Look Left, Look Right Again, listen for vehicles, and cross only when traffic has stopped', "Close your eyes and hold your friend's hand tightly", 'Look behind you and walk backward across the street'], 'answer': 1, 'explanation': "In India's left-hand traffic system, oncoming vehicles approach from your right first. Looking Right, Left, and Right Again ensures clear vision before crossing.", 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Defensive Crossing Rule:</strong></p>\n                <p>Because traffic drives on the left in India, the lane closest to you carries vehicles from your right. Looking Right first checks immediate danger; looking Left checks the second lane; looking Right once more ensures no vehicle has turned in.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the life-saving rule.</p>\n            </div>\n        '}, {'id': 27, 'question': "Which geometric shape and color code signify 'Mandatory / Regulatory' traffic signs that drivers MUST obey by law?", 'options': ['Blue rectangles with white lettering', 'Circular signs with bold red borders (such as Stop, No Entry, Speed Limit)', 'Yellow triangles pointing downward', 'Green octagons with pink stripes'], 'answer': 1, 'explanation': 'Circular signs with red borders are mandatory regulatory signs. Violating them is a direct breach of traffic law.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Mandatory Road Signs:</strong></p>\n                <p>Mandatory traffic signs issue direct legal commands. They are circular with a red ring border (like \'No Parking\' or \'Speed Limit 20\'). The iconic \'STOP\' sign is uniquely octagonal, and \'GIVE WAY\' is an inverted triangle.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the mandatory sign format.</p>\n            </div>\n        '}, {'id': 28, 'question': 'What does a triangular traffic sign with a red border depicting silhouettes of two school children walking signify to drivers?', 'options': ['Children are forbidden from walking on the footpath', "Cautionary warning: 'School Ahead'—drivers must slow down and watch out for crossing children", 'A toy store is open 24 hours ahead', 'The road is reserved only for school buses'], 'answer': 1, 'explanation': "Triangular signs are cautionary. The 'School Ahead' sign alerts motorists to reduce speed and remain vigilant for young pedestrians.", 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Cautionary Traffic Signs:</strong></p>\n                <p>Warning signs are equilateral triangles pointing up with red borders. The \'School Ahead\' sign warns drivers that children are likely to be crossing, requiring immediate deceleration and alert driving.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the correct meaning.</p>\n            </div>\n        '}, {'id': 29, 'question': 'What is the purpose of rectangular traffic signs with blue backgrounds located near school campuses?', 'options': ['They are decorative advertisements for sports brands', 'Informatory signs providing directions and useful facilities (such as Hospital, Bus Stop, or Pedestrian Crossing)', 'They indicate that the road is underwater', 'They command drivers to accelerate immediately'], 'answer': 1, 'explanation': 'Rectangular blue signs are informatory, providing helpful navigation, facility locations, and public service information to commuters.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Informatory Road Signs:</strong></p>\n                <p>Informatory signs guide road users without giving legal orders or warnings. They feature blue rectangles with white symbols indicating hospitals, public transit stops, parking zones, and first aid stations.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B defines informatory signs.</p>\n            </div>\n        '}, {'id': 30, 'question': 'What is the legal rule regarding painted zebra crossings marked across roads outside school gates?', 'options': ['Vehicles should speed up to pass pedestrians before they step onto the road', 'Pedestrians have absolute right-of-way; drivers must slow down and stop before the line when pedestrians are crossing', 'Zebra crossings are parking spots for school delivery trucks', 'Only zebras from the zoo are permitted to cross on the stripes'], 'answer': 1, 'explanation': 'Zebra crossings give pedestrians right-of-way. Motorists must yield and come to a complete halt before the stop line to let pedestrians cross safely.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Zebra Crossing Pedestrian Priority:</strong></p>\n                <p>Painted alternating white and black stripes designate pedestrian crosswalks. Traffic laws mandate that vehicles must yield right-of-way to pedestrians on or entering a zebra crossing, coming to a complete stop.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the legal rule.</p>\n            </div>\n        '}, {'id': 31, 'question': 'What is the critical personal conduct rule when a school fire alarm rings loudly during class?', 'options': ['Sprint as fast as you can, shouting and pushing past everyone on the stairs', 'Stay calm, do not panic, leave school bags behind, and walk quickly in a single-file line toward the exit', 'Lock the classroom door and hide underneath wooden benches', 'Search for lost stationery in your backpack'], 'answer': 1, 'explanation': 'Panic and running cause stampedes and injuries. Walking briskly and calmly in a single file ensures a fast, safe, orderly evacuation.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Orderly Evacuation vs Stampede:</strong></p>\n                <p>In fire emergencies, human stampedes and falling down staircases often cause more physical harm than the fire itself. Leaving heavy bags behind and walking calmly in single file ensures everyone gets out safely.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the correct emergency conduct.</p>\n            </div>\n        '}, {'id': 32, 'question': 'Why do hot smoke, poisonous gases, and black soot rise rapidly toward the ceiling during a building fire?', 'options': ['Because smoke is attracted to ceiling lights by magnetism', 'Thermal convection: hot air and combustion gases are less dense than cooler room air, making them buoyant and rise', 'Because gravity reverses its direction during fires', 'Smoke only moves toward dark ceiling corners'], 'answer': 1, 'explanation': 'Hot air and combustion gases expand and become less dense than surrounding air, causing thermal convection currents that push smoke up against the ceiling.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Thermal Convection Physics:</strong></p>\n                <p>Heated gases expand, decreasing in density ($\rho = m/V$). The cooler, denser air pushes the superheated smoke upward. Consequently, the hottest and most toxic fumes accumulate in a thick layer starting at the ceiling and slowly descending.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B explains why smoke rises.</p>\n            </div>\n        '}, {'id': 33, 'question': "What is the life-saving 'Crawl Low under Smoke' technique used when escaping a smoke-filled hallway?", 'options': ['Standing on tiptoes and jumping through the smoke', 'Dropping onto hands and knees where the coolest, cleanest, breathable air remains 30 to 60 cm above the floor', 'Rolling backward down staircases', 'Lying completely still and closing eyes'], 'answer': 1, 'explanation': 'The cleanest air with the highest oxygen and lowest temperature stays in a 30 to 60 cm layer near the floor. Crawling low avoids inhaling lethal toxic smoke.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>The Mechanics of Crawling Low:</strong></p>\n                <p>Dropping to hands and knees keeps your nose and mouth in the lowest, coolest air zone. Covering your face with a cloth helps filter soot particles. Keeping your head in the bottom 30-60 cm allows you to see exit signs and breathe safely.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the life-saving method.</p>\n            </div>\n        '}, {'id': 34, 'question': 'Why is it strictly forbidden to hide inside cupboards, closets, or washrooms during a building fire?', 'options': ["Closets are reserved only for teachers' coats", 'Hiding traps you in dead-end confined spaces without escape exits, making it extremely difficult for rescue firefighters to find you in thick smoke', 'Washrooms have no water taps', 'Cupboards make fire alarms ring louder'], 'answer': 1, 'explanation': 'Hiding traps students in confined areas with no secondary escape. Firefighters searching rapidly through smoke-filled rooms may miss closed closets.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>The Danger of Hiding in Emergencies:</strong></p>\n                <p>Young children often hide out of fear. But closed closets and bathrooms quickly fill with toxic smoke through vents, trapping occupants. Always move toward emergency exits, and never hide.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B explains why hiding is dangerous.</p>\n            </div>\n        '}, {'id': 35, 'question': 'What essential procedure must take place immediately after reaching the open assembly point during a school fire drill?', 'options': ['Students run home without telling anyone', 'Students assemble in their designated class lines so teachers can take attendance and account for every child', 'Students start playing cricket immediately', 'Students run back inside to inspect the flames'], 'answer': 1, 'explanation': 'Roll call at the muster point ensures that every student is accounted for. If a student is missing, teachers can immediately alert emergency firefighters.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Assembly Point Roll Call:</strong></p>\n                <p>Reaching the assembly point is not the end of the drill. Standing quietly in class lines allows teachers to take attendance. If anyone is unaccounted for, emergency rescue teams are dispatched immediately to the exact missing location.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the vital roll call step.</p>\n            </div>\n        '}, {'id': 36, 'question': 'Why is scribbling graffiti or carving marks into wooden school desks and library books considered harmful and unacceptable?', 'options': ['It turns the desks into pure stone', 'Desks and books are shared community property; defacing them damages school heritage and deprives future students of clean resources', 'Permanent ink dissolves wood into water', 'Desks will stop holding notebooks'], 'answer': 1, 'explanation': 'School furniture and library books are shared public goods. Protecting them preserves resources and shows respect for the learning community.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Public Property Stewardship:</strong></p>\n                <p>Civic responsibility means treating shared school facilities with the same care as personal belongings at home. Preserving clean desks and books ensures that younger students entering the school next year inherit a beautiful, welcoming campus.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the civic principle.</p>\n            </div>\n        '}, {'id': 37, 'question': 'How does showing empathy and kindness transform a school into a truly happy place?', 'options': ['It eliminates all homework permanently', 'It makes every student feel valued, included, and emotionally safe, eliminating fear and bullying', 'It turns classroom lights off forever', 'It makes students stop talking to each other'], 'answer': 1, 'explanation': 'Empathy fosters mutual respect, trust, and emotional safety, creating a supportive environment where children can thrive and learn without fear.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Social-Emotional Climate:</strong></p>\n                <p>When students practice empathy—listening, taking turns, welcoming lonely classmates, and offering help—the school becomes a community of trust. Emotional safety is the foundation of high academic engagement and joy.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the transformative power of empathy.</p>\n            </div>\n        '}, {'id': 38, 'question': 'What is the recommended gentle slope (gradient) for wheelchair entrance ramps in accessible schools?', 'options': ['A vertical 90° drop like a ladder', 'A gentle slope of at least 1:12 (1 unit rise for every 12 units of ramp length) equipped with continuous handrails', 'A steep 1:2 ramp so wheelchairs slide down fast', 'Zero ramp, stairs are sufficient for all wheels'], 'answer': 1, 'explanation': 'A 1:12 slope ensures that wheelchair users can wheel themselves up safely without excessive effort, loss of balance, or tipping backward.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Universal Ramp Design:</strong></p>\n                <p>Accessibility standards mandate a slope no steeper than 1:12 (approx. 4.8° angle), along with non-slip flooring, double handrails at two heights, and a level landing platform at the top and bottom.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the accessibility standard.</p>\n            </div>\n        '}, {'id': 39, 'question': 'What is the tactile difference between straight directional lines and raised round dots on yellow guiding floor tiles?', 'options': ['Lines mean stop, while dots mean run', 'Straight raised lines indicate a safe, clear walking path, while raised round dots warn of hazards, doors, turns, or approaching stairs', 'Dots are for playing games, while lines are for parking bicycles', 'There is no difference between them'], 'answer': 1, 'explanation': 'In tactile ground surface indicators, directional linear bars guide along paths, while hazard blister dots signal attention, turns, or staircases.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>Tactile Paving Standards:</strong></p>\n                <p>Visually impaired individuals feel these floor textures through walking canes or footwear. Linear \'guiding tiles\' show safe corridors; truncated \'blister tiles\' warn that stairs, platforms, or intersections lie immediately ahead.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B describes the tactile code.</p>\n            </div>\n        '}, {'id': 40, 'question': "What is the lasting purpose of creating a campus 'Happiness Tree' bulletin display?", 'options': ['To sell paper leaves to visitors for money', 'To visually celebrate student acts of kindness, environmental stewardship, and gratitude, inspiring a caring school culture', 'To replace living garden trees with cardboard', 'To list disciplinary warnings for students'], 'answer': 1, 'explanation': 'The Happiness Tree serves as an ongoing visual testament to kindness, sustainable eco-actions, and mutual gratitude, reinforcing a supportive community.', 'solution_html': '\n            <div class="space-y-2 text-xs">\n                <p><strong>The Happiness Tree Celebration:</strong></p>\n                <p>By writing and pinning leaves representing kind acts, water savings, tree planting, and thank-you notes to staff, students build a shared identity of empathy, ecological responsibility, and pride in their school.</p>\n                <p class="text-cyan-300"><strong>Conclusion:</strong> Option B is the purpose of the Happiness Tree.</p>\n            </div>\n        '}]
